/** In-story lines only. Keyed by lyric file id. */
export const A = {};

function put(id, n, body) {
	const lines = body
		.split('\n')
		.map((s) => s.trim())
		.filter((s) => s.length > 0);
	if (lines.length !== n) {
		console.error(`${id}: ${lines.length} lines, wanted ${n}`);
	}
	A[id] = lines;
}

